$ErrorActionPreference='Stop'
$target='C:\Users\M\CLINE\tools\automation_server.py'
$stamp=Get-Date -Format 'yyyy-MM-dd_HHmmss'
$bak="C:\Users\M\CLINE\BACKUPS\$stamp\CLINE\tools"
New-Item -ItemType Directory -Path $bak -Force|Out-Null
Copy-Item -LiteralPath $target -Destination (Join-Path $bak 'automation_server.py')
Write-Output ('BACKUP='+$bak)
$conn=Get-NetTCPConnection -LocalPort 8792 -State Listen -ErrorAction SilentlyContinue|Select-Object -First 1
if($conn){$owner=[int]$conn.OwningProcess;$proc=Get-CimInstance Win32_Process -Filter "ProcessId=$owner";if($proc.CommandLine -notmatch 'automation_server.py'){throw 'Porto 8792 savininkas nera musu serveris'};Write-Output ('STOP_AUTOMATION_PID='+$owner);Stop-Process -Id $owner -Force}
for($i=0;$i -lt 20;$i++){Start-Sleep -Milliseconds 400;if(-not (Get-NetTCPConnection -LocalPort 8792 -State Listen -ErrorAction SilentlyContinue)){break}}
[IO.File]::WriteAllBytes($target,[Convert]::FromBase64String(''))
& 'C:\Users\M\AppData\Local\Programs\Python\Python312\python.exe' -m py_compile $target
Write-Output ('PY_COMPILE='+$LASTEXITCODE)
$loop='C:\Users\M\CLINE\tools\automation-server-loop.ps1'
Start-Process -FilePath 'C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe' -ArgumentList @('-NoProfile','-WindowStyle','Hidden','-ExecutionPolicy','Bypass','-File',$loop) -WindowStyle Hidden
$ok=$false
for($i=0;$i -lt 30;$i++){Start-Sleep -Milliseconds 500;try{$h=Invoke-WebRequest 'http://127.0.0.1:8792/health' -UseBasicParsing -TimeoutSec 2;if($h.StatusCode -eq 200){$ok=$true;break}}catch{}}
Write-Output ('HEALTH_OK='+$ok)
if(-not $ok){throw 'Serveris nepaleistas'}
$token=(Get-Content -LiteralPath 'C:\Users\M\CLINE\tools\automation-secret.txt' -Raw).Trim()
foreach($action in @('ensure','collect','collect')){
 $sw=[Diagnostics.Stopwatch]::StartNew()
 $r=& curl.exe -sS --max-time 45 -X POST -H "X-Automation-Key: $token" -w "|HTTP=%{http_code}|T=%{time_total}" ('http://127.0.0.1:8792/'+$action) 2>&1 | Out-String
 $sw.Stop()
 Write-Output ($action+' => '+($r.Trim()))
}
Write-Output '===== API LOG ====='
Get-Content -LiteralPath 'C:\Users\M\CLINE\AUTOMATION_API_LOG.txt' -Encoding UTF8 -Tail 8
